mapper.select:
/* selectDeptTotalList */ SELECT C.BUYER, C.REQ_DEPT, MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = C.BUYER AND TYPE = 'C001' AND CODE = C.REQ_DEPT)) AS REQ_DEPT_NAME, SUM(NVL(B.ITEM_AMT, 0)) AS PO_AMT, SUM(NVL(D.ITEM_AMT, 0)) AS GR_AMT, COUNT(NVL(B.PO_SEQ, 0)) AS PO_COUNT FROM ICOMPOHD A, ICOMPODT B, ICOMPRDT C, ( SELECT BUYER, PO_NO, PO_SEQ, SUM(ITEM_AMT) AS ITEM_AMT FROM ICOMGRDT WHERE BUYER = #{buyer} AND STATUS <> 'D' GROUP BY BUYER, PO_NO, PO_SEQ ) D WHERE 1=1 AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND B.BUYER = C.BUYER AND B.PR_NO = C.PR_NO AND B.PR_SEQ = C.PR_SEQ AND B.PO_NO = D.PO_NO(+) AND B.PO_SEQ = D.PO_SEQ(+) AND B.BUYER = D.BUYER(+) AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND A.BUYER = #{buyer} AND A.PO_CREATE_DATE BETWEEN #{fromDate} AND #{toDate}
AND C.REQ_DEPT = #{st_dept_code}
AND A.AGENT = #{st_dept_code}
AND C.BUYER_ITEM_NO = #{itemNo}
AND C.DESCRIPTION LIKE '%' || #{itemNo} || '%'
AND C.SPECIFICATION LIKE '%' || #{itemNo} || '%'
AND C.REF_NO LIKE '%' || #{orderNo} || '%'
AND B.PO_NO LIKE '%' || #{orderNo} || '%'
AND C.PR_NO LIKE '%' || #{orderNo} || '%'
AND (C.REF_PR_NO LIKE '%' || #{orderNo} || '%' OR C.LEGACY_PO_NO LIKE '%' || #{orderNo} || '%')
AND C.REF_IF_NO LIKE '%' || #{orderNo} || '%'
AND C.LEGACY_PO_NO || '-' || C.LEGACY_PO_SEQ LIKE '%' || #{orderNo} || '%'
AND F_GET_PX_STTS(C.BUYER, C.PR_NO, C.PR_SEQ, 0) = #{status_code}
GROUP BY C.BUYER, C.REQ_DEPT
ORDER BY 4
ORDER BY 5
ORDER BY 3

/* selectSuplTotalList */ SELECT C.BUYER, A.AGENT, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT)) AS AGENT_NAME, SUM(NVL(B.ITEM_AMT, 0)) AS PO_AMT, SUM(NVL(D.ITEM_AMT, 0)) AS GR_AMT, COUNT(NVL(B.PO_SEQ, 0)) AS PO_COUNT FROM ICOMPOHD A, ICOMPODT B, ICOMPRDT C, ( SELECT BUYER, PO_NO, PO_SEQ, SUM(ITEM_AMT) AS ITEM_AMT FROM ICOMGRDT WHERE BUYER = #{buyer} AND STATUS <> 'D' GROUP BY BUYER, PO_NO, PO_SEQ ) D WHERE 1=1 AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND B.BUYER = C.BUYER AND B.PR_NO = C.PR_NO AND B.PR_SEQ = C.PR_SEQ AND B.PO_NO = D.PO_NO(+) AND B.PO_SEQ = D.PO_SEQ(+) AND B.BUYER = D.BUYER(+) AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND A.BUYER = #{buyer} AND A.PO_CREATE_DATE BETWEEN #{fromDate} AND #{toDate}
AND C.REQ_DEPT = #{st_dept_code}
AND A.AGENT = #{st_dept_code}
AND C.BUYER_ITEM_NO = #{itemNo}
AND C.DESCRIPTION LIKE '%' || #{itemNo} || '%'
AND C.SPECIFICATION LIKE '%' || #{itemNo} || '%'
AND C.REF_NO LIKE '%' || #{orderNo} || '%'
AND B.PO_NO LIKE '%' || #{orderNo} || '%'
AND C.PR_NO LIKE '%' || #{orderNo} || '%'
AND (C.REF_PR_NO LIKE '%' || #{orderNo} || '%' OR C.LEGACY_PO_NO LIKE '%' || #{orderNo} || '%')
AND C.REF_IF_NO LIKE '%' || #{orderNo} || '%'
AND C.LEGACY_PO_NO || '-' || C.LEGACY_PO_SEQ LIKE '%' || #{orderNo} || '%'
AND F_GET_PX_STTS(C.BUYER, C.PR_NO, C.PR_SEQ, 0) = #{status_code}
GROUP BY C.BUYER, A.AGENT
ORDER BY 4
ORDER BY 5
ORDER BY 3

/* selectRefTotalList */ SELECT C.BUYER, C.REF_PR_NO, SUM(NVL(B.ITEM_AMT, 0)) AS PO_AMT, SUM(NVL(D.ITEM_AMT, 0)) AS GR_AMT, COUNT(NVL(B.PO_SEQ, 0)) AS PO_COUNT FROM ICOMPOHD A, ICOMPODT B, ICOMPRDT C, ( SELECT BUYER, PO_NO, PO_SEQ, SUM(ITEM_AMT) AS ITEM_AMT FROM ICOMGRDT WHERE BUYER = #{buyer} AND STATUS <> 'D' GROUP BY BUYER, PO_NO, PO_SEQ ) D WHERE 1=1 AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND B.BUYER = C.BUYER AND B.PR_NO = C.PR_NO AND B.PR_SEQ = C.PR_SEQ AND B.PO_NO = D.PO_NO(+) AND B.PO_SEQ = D.PO_SEQ(+) AND B.BUYER = D.BUYER(+) AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND A.BUYER = #{buyer} AND A.PO_CREATE_DATE BETWEEN #{fromDate} AND #{toDate}
AND C.REQ_DEPT = #{st_dept_code}
AND A.AGENT = #{st_dept_code}
AND C.BUYER_ITEM_NO = #{itemNo}
AND C.DESCRIPTION LIKE '%' || #{itemNo} || '%'
AND C.SPECIFICATION LIKE '%' || #{itemNo} || '%'
AND C.REF_NO LIKE '%' || #{orderNo} || '%'
AND B.PO_NO LIKE '%' || #{orderNo} || '%'
AND C.PR_NO LIKE '%' || #{orderNo} || '%'
AND (C.REF_PR_NO LIKE '%' || #{orderNo} || '%' OR C.LEGACY_PO_NO LIKE '%' || #{orderNo} || '%')
AND C.REF_IF_NO LIKE '%' || #{orderNo} || '%'
AND C.LEGACY_PO_NO || '-' || C.LEGACY_PO_SEQ LIKE '%' || #{orderNo} || '%'
AND F_GET_PX_STTS(C.BUYER, C.PR_NO, C.PR_SEQ, 0) = #{status_code}
GROUP BY C.BUYER, C.REF_PR_NO
ORDER BY 3
ORDER BY 4
ORDER BY 2
